def _brand_icon_uri(platform):
    """Повертає data:-URI круглого значка платформи (SVG, без мережі)."""
    path = _BRAND_GLYPH_PATHS[platform]
    fit = "transform='translate(12 12) scale({}) translate(-12 -12)'"
    if platform == "tiktok":
        body = ("<circle cx='12' cy='12' r='12' fill='#000'/><g {t}>"
                "<path fill='#25F4EE' transform='translate(-0.7 -0.5)' d='{d}'/>"
                "<path fill='#FE2C55' transform='translate(0.7 0.5)' d='{d}'/>"
                "<path fill='#fff' d='{d}'/></g>").format(t=fit.format("0.52"), d=path)
    else:
        fill, glyph, scale = {
            "twitch": ("#9146FF", "#fff", "0.58"),
            "youtube": ("#FF0000", "#fff", "0.62"),
            "kick": ("#53FC18", "#000", "0.5"),
        }[platform]
        body = "<circle cx='12' cy='12' r='12' fill='{}'/><path fill='{}' {} d='{}'/>".format(
            fill, glyph, fit.format(scale), path)
    svg = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'>" + body + "</svg>"
    return "data:image/svg+xml;base64," + base64.b64encode(svg.encode("utf-8")).decode("ascii")


