def obs_guide_text(port):
    out = []
    for title, items in OBS_GUIDE:
        out.append(title)
        for txt, url in items:
            out.append("- " + txt.replace("{port}", str(port)) + ((" [" + url + "]") if url else ""))
        out.append("")
    return "\n".join(out)


def obs_guide_html(port):
    import html as _h
    out = ["<br><b>ДОВІДНИК ПО РОЗДІЛАХ ПАНЕЛІ НАЛАШТУВАНЬ</b><br>"]
    for title, items in OBS_GUIDE:
        out.append("<br><b>{}</b><br>".format(_h.escape(title)))
        for txt, url in items:
            line = _h.escape(txt.replace("{port}", str(port)))
            if url:
                line += ' <a href="{0}">{0}</a>'.format(_h.escape(url))
            out.append("• " + line + "<br>")
    return "".join(out)


